insert into posts (author_id, kind, body, about_org_id, created_at) values
  ('00000000-0000-4000-c000-000000000434', 'update', 'If you''re in Portland and free on a Saturday afternoon, Harbor Table needs dinner crew. I went last week for the first time: four hours, no experience, and I''ve never felt more useful. They feed anyone who walks in, no questions asked.', '00000000-0000-4000-a000-000000000001', now() - interval '14 hours'),
  ('00000000-0000-4000-c000-000000000388', 'update', 'Biscuit spent 214 days at Second Chance Paws before she got adopted. If you can walk a dog for an hour a week, the long-stay dogs need you most. That''s how they stay happy enough to get picked.', '00000000-0000-4000-a000-000000000007', now() - interval '29 hours'),
  ('00000000-0000-4000-c000-000000000799', 'update', 'Started giving monthly this year instead of a big check in December. Smaller amounts, but the orgs I support can actually plan around it. If you can, try recurring. They all say it''s the most useful kind of gift.', null, now() - interval '43 hours'),
  ('00000000-0000-4000-c000-000000000230', 'update', 'Bridge Welcome Center is looking for airport welcome drivers. My cousin''s family arrived at 2 am two years ago and a volunteer was there with a sign and snacks. It changed their first night completely.', '00000000-0000-4000-a000-000000000011', now() - interval '55 hours'),
  ('00000000-0000-4000-c000-000000000200', 'update', 'Free blood pressure and diabetes screening at the Eastside rec center this Thursday, with Spanish and Somali interpreters. Neighborhood Health Corps follows up until you have a doctor. Please share with anyone who needs it.', '00000000-0000-4000-a000-000000000014', now() - interval '70 hours'),
  ('00000000-0000-4000-c000-000000000692', 'update', 'Our block got 46 new street trees last spring. This summer it was noticeably cooler on the sidewalk. Rooted Neighborhoods is taking nominations for spring planting. Nominate your block!', '00000000-0000-4000-a000-000000000008', now() - interval '82 hours'),
  ('00000000-0000-4000-c000-000000000736', 'update', 'Reminder that a lot of employers match donations, and most people never ask. I found out mine matches up to $1,000 a year. Five minutes on the HR site doubled what I gave.', null, now() - interval '94 hours'),
  ('00000000-0000-4000-c000-000000000585', 'update', 'Fostered my first litter of bottle babies with Foster Kitten Network this month. Every two hours, day and night, for three weeks. All four are gaining weight and going up for adoption Saturday. Exhausting and the best thing I''ve done all year.', '00000000-0000-4000-a000-000000000036', now() - interval '108 hours'),
  ('00000000-0000-4000-c000-000000000900', 'update', 'Hearth & Home is running low on move-in kits: sheets, towels, pots, a shower curtain. Twenty-two guests moved into their own apartments last quarter. A kit is what makes the first night feel like home.', '00000000-0000-4000-a000-000000000021', now() - interval '122 hours'),
  ('00000000-0000-4000-c000-000000000454', 'update', 'Did two warehouse shifts at Prairie Wind Food Bank this week. We sorted enough sweet corn and squash for 41 school backpack programs. They need sorters through the holidays, no experience needed.', '00000000-0000-4000-a000-000000000028', now() - interval '134 hours'),
  ('00000000-0000-4000-c000-000000000073', 'update', 'Read with a first grader at Riverbend Readers today. He read me a whole chapter book, out loud, and asked to keep it. They''re always looking for Tuesday afternoon tutors.', '00000000-0000-4000-a000-000000000003', now() - interval '149 hours'),
  ('00000000-0000-4000-c000-000000000836', 'update', 'What I''ve learned from following orgs here: the best ones post the boring updates too. Freezer repaired, volunteers trained, waitlist down. That''s how you know the money''s working.', null, now() - interval '163 hours'),
  ('00000000-0000-4000-c000-000000000925', 'update', 'If your company is upgrading laptops, Bright Lines Coding Club refurbishes them for teens to borrow. Their demo night was incredible: a bus tracker one school now actually uses.', '00000000-0000-4000-a000-000000000034', now() - interval '175 hours'),
  ('00000000-0000-4000-c000-000000000418', 'update', 'Spent Saturday knee-deep in Mill Creek with Blue Heron Watershed. Water testing shows nitrate down for the third year in a row. Creek cleanups are the second Saturday of every month and they lend you waders.', '00000000-0000-4000-a000-000000000019', now() - interval '194 hours'),
  ('00000000-0000-4000-c000-000000000372', 'update', 'Clear Minds Collective''s warm line isn''t a crisis line. It''s someone who''s been there, to talk to before things get that bad. Sharing in case anyone needs it this week.', '00000000-0000-4000-a000-000000000012', now() - interval '209 hours'),
  ('00000000-0000-4000-c000-000000000964', 'update', 'Had dinner at Shared Table''s pay-what-you-can night. Eritrean lentils and injera, made by trainees who''ll be working in restaurant kitchens in a few weeks. Go hungry, bring friends.', '00000000-0000-4000-a000-000000000024', now() - interval '226 hours'),
  ('00000000-0000-4000-c000-000000000147', 'update', 'My kids and I pick one organization each year to give to together. This year my daughter picked the little libraries in laundromats because ''people get bored waiting.'' Hard to argue.', null, now() - interval '245 hours'),
  ('00000000-0000-4000-c000-000000000784', 'update', 'Hilltop Senior Meals needs drivers for north end routes. It''s about 90 minutes on a weekday. My Tuesday route includes a 92-year-old who beats me at cribbage every single week.', '00000000-0000-4000-a000-000000000031', now() - interval '264 hours'),
  ('00000000-0000-4000-c000-000000000706', 'update', 'Love that the Lakeshore Community Foundation publishes every grant, and the nonprofits confirm them. Giving through the Community Fund feels a lot less like a black box when you can see exactly where it went.', '00000000-0000-4000-a000-000000000005', now() - interval '286 hours'),
  ('00000000-0000-4000-c000-000000000947', 'update', 'Mobile Dental Neighbors saw 410 kids this fall, 180 of them for their first dental visit. If you''re a hygienist with a free Saturday, they need you at shelter visits.', '00000000-0000-4000-a000-000000000027', now() - interval '302 hours'),
  ('00000000-0000-4000-c000-000000000138', 'update', 'Volunteered for the first time this year after reading posts here for months. Nobody cared that I had no experience. Just show up.', null, now() - interval '319 hours'),
  ('00000000-0000-4000-c000-000000000052', 'update', 'The Seedline Growers stand at the Saturday market sells out of amaranth greens every week. Buying from refugee farmers'' first businesses is one of the easiest ways to help.', '00000000-0000-4000-a000-000000000033', now() - interval '338 hours'),
  ('00000000-0000-4000-c000-000000000347', 'update', 'Keystone Housing''s Wednesday tenant clinic helped my neighbor keep her apartment after a medical emergency. Free legal advice, interpreters, and someone who actually explains the paperwork.', '00000000-0000-4000-a000-000000000017', now() - interval '360 hours'),
  ('00000000-0000-4000-c000-000000000451', 'update', 'The new mural by Westside Arts Studio teens went up on the 3rd Street underpass. The whole neighborhood voted on the design. Go see it in person if you can.', '00000000-0000-4000-a000-000000000009', now() - interval '389 hours'),
  ('00000000-0000-4000-c000-000000000398', 'update', 'Saw Saltmarsh Wildlife Rescue release two pelicans this morning. They came in tangled in fishing line in August. Please cut your line before you bin it.', '00000000-0000-4000-a000-000000000022', now() - interval '408 hours'),
  ('00000000-0000-4000-c000-000000000640', 'update', 'Giving tip: check what a nonprofit says their gift amounts actually fund. ''$25 covers a week of dinners for one neighbor'' tells you way more than a mission statement.', null, now() - interval '442 hours'),
  ('00000000-0000-4000-c000-000000000775', 'update', 'Little Oak Early Learning runs on a sliding scale so every kid gets preschool. They''re asking for picture books with diverse families. Their wish list is on their site.', '00000000-0000-4000-a000-000000000026', now() - interval '463 hours'),
  ('00000000-0000-4000-c000-000000000077', 'update', 'Northside Youth Soccer is free for every kid, and their cleat closet is empty in sizes 3 to 6. If your kids have outgrown theirs, Saturday practice is the drop-off.', '00000000-0000-4000-a000-000000000010', now() - interval '492 hours'),
  ('00000000-0000-4000-c000-000000000930', 'update', 'Quiet Hours Hospice Volunteers sat with my grandfather through his last nights so my mom could sleep. Their January training class is open if you have patience and four Saturday mornings.', '00000000-0000-4000-a000-000000000035', now() - interval '528 hours'),
  ('00000000-0000-4000-c000-000000000366', 'update', 'Rode along on an Eastgate Food Rescue night route. 19 stops, 4,100 pounds of food that would''ve been thrown out, on pantry shelves by 7 am. They need drivers for one route a week.', '00000000-0000-4000-a000-000000000016', now() - interval '569 hours'),
  ('00000000-0000-4000-c000-000000000596', 'update', 'Two years of logging my gifts in the giving journal here. Turns out I gave way more to hunger and housing than I thought, and almost nothing to the environment. Changing that this year.', null, now() - interval '602 hours'),
  ('00000000-0000-4000-c000-000000000637', 'update', 'Open Shelves just installed three new little libraries, including the Route 9 bus shelter. Picture books go fastest. Book drive at the library through Friday.', '00000000-0000-4000-a000-000000000013', now() - interval '634 hours'),
  ('00000000-0000-4000-c000-000000000084', 'update', 'Alder Family Foundation moved most of its grants to three-year operating support because grantees asked. More funders should do this.', '00000000-0000-4000-a000-000000000039', now() - interval '672 hours'),
  ('00000000-0000-4000-c000-000000000711', 'update', 'Open Gate Youth Shelter''s drop-in center is open until 10 pm now, with dinner, showers and laundry. They need phone chargers and prepaid phone cards.', '00000000-0000-4000-a000-000000000030', now() - interval '725 hours'),
  ('00000000-0000-4000-c000-000000000977', 'update', 'Steady Path''s recovery coaches are in the county ER every night now. A coach sat with my brother at 3 am two years ago. This month he finished coach training himself.', '00000000-0000-4000-a000-000000000025', now() - interval '804 hours'),
  ('00000000-0000-4000-c000-000000000495', 'update', 'If you''ve been meaning to give but feel like your amount is too small: every org I''ve talked to says $10 a month from a hundred people is worth more to them than one big gift.', null, now() - interval '864 hours');
insert into posts (author_id, kind, body, about_org_id, image_paths, image_alts, image_credits, beneficiary_consent, created_at) values
  ('00000000-0000-4000-c000-000000000003', 'update', 'Two-hour sorting shift at the food bank this morning. We got through a full truck of donated produce. If you''ve never done it, the energy in that warehouse is something else.', '00000000-0000-4000-a000-000000000028', array['people/00000000-0000-4000-c000-000000000003/2015-feds-feeds-families-gleanin-3c6a93.webp']::text[], array['Volunteers sorting donated produce in a warehouse']::text[], array['USDAgov, Public domain, via Wikimedia Commons']::text[], true, now() - interval '10 hours'),
  ('00000000-0000-4000-c000-000000000017', 'update', 'Brought my whole team from work to the food bank instead of a happy hour. Best offsite we''ve ever had.', '00000000-0000-4000-a000-000000000028', array['people/00000000-0000-4000-c000-000000000017/2015-feds-feeds-families-gleanin-04bb4e.webp']::text[], array['A volunteer bagging potatoes']::text[], array['USDAgov, Public domain, via Wikimedia Commons']::text[], true, now() - interval '50 hours'),
  ('00000000-0000-4000-c000-000000000029', 'update', 'Gleaning day with Eastgate: we sorted a full truck of potatoes and greens that would''ve been tossed. Every bag goes to a pantry tomorrow morning.', '00000000-0000-4000-a000-000000000016', array['people/00000000-0000-4000-c000-000000000029/2015-feds-feeds-families-gleanin-6c685b.webp', 'people/00000000-0000-4000-c000-000000000029/2015-feds-feeds-families-gleanin-81845a.webp']::text[], array['A volunteer sorting potatoes into a bin', 'Volunteers bagging produce in a warehouse']::text[], array['USDAgov, Public domain, via Wikimedia Commons', 'USDAgov, Public domain, via Wikimedia Commons']::text[], true, now() - interval '36 hours'),
  ('00000000-0000-4000-c000-000000000041', 'update', 'Trail day with Greenway Stewards. My arms are sore and the trail is clear. They bring the tools and lunch; you bring yourself.', '00000000-0000-4000-a000-000000000004', array['people/00000000-0000-4000-c000-000000000041/deer-hill-trail-national-public-94ce20.webp', 'people/00000000-0000-4000-c000-000000000041/deer-hill-trail-national-public-16c09d.webp']::text[], array['A volunteer in a hard hat clearing branches from a pine', 'A volunteer cutting a dead branch on a forest trail']::text[], array['Coconino National Forest, Public domain, via Wikimedia Commons', 'Coconino National Forest, Public domain, via Wikimedia Commons']::text[], true, now() - interval '77 hours'),
  ('00000000-0000-4000-c000-000000000058', 'update', 'Planted my first tree with Rooted Neighborhoods. Somebody''s kid will sit in its shade someday.', '00000000-0000-4000-a000-000000000008', array['people/00000000-0000-4000-c000-000000000058/aufbuchen-planting-schlachtensee-895bd9.webp']::text[], array['Volunteers planting saplings on a forest floor']::text[], array['RobbieIanMorrison, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, now() - interval '96 hours'),
  ('00000000-0000-4000-c000-000000000066', 'update', 'Spent Saturday replanting a burned hillside with Blue Heron''s crew. Strangers at 8 am, friends by noon.', '00000000-0000-4000-a000-000000000019', array['people/00000000-0000-4000-c000-000000000066/sharps-fire-planting-and-habitat-c9a010.webp', 'people/00000000-0000-4000-c000-000000000066/sharps-fire-planting-and-habitat-75bd0c.webp']::text[], array['Two volunteers in work gloves sorting seedlings', 'A volunteer planting in a wide dry valley']::text[], array['BLMIdaho, Public domain, via Wikimedia Commons', 'BLMIdaho, Public domain, via Wikimedia Commons']::text[], true, now() - interval '115 hours'),
  ('00000000-0000-4000-c000-000000000077', 'update', 'My Wednesday walking buddy. He''s been at Second Chance Paws for five months and is the best boy. Ask for Rocket.', '00000000-0000-4000-a000-000000000007', array['people/00000000-0000-4000-c000-000000000077/american-soldiers-volunteer-at-g-ef6d50.webp']::text[], array['A volunteer walking a shelter dog on a wood-chip path']::text[], array['U.S. Army photo by 1st Lt. Jonathan Hankey, Public domain, via Wikimedia Commons']::text[], true, now() - interval '26 hours'),
  ('00000000-0000-4000-c000-000000000085', 'update', 'Group walk at the shelter. Six dogs, six volunteers, one very muddy field. Come join us on Sundays.', '00000000-0000-4000-a000-000000000007', array['people/00000000-0000-4000-c000-000000000085/deployed-soldiers-volunteer-at-a-f174a2.webp']::text[], array['Volunteers walking dogs across a grassy yard']::text[], array['U.S. Army photo by Spc. Elsi Delgado, Public domain, via Wikimedia Commons']::text[], true, now() - interval '151 hours'),
  ('00000000-0000-4000-c000-000000000093', 'update', 'Helped out in the Shared Table kitchen for their trainee graduation dinner. These cooks are about to make some restaurant very lucky.', '00000000-0000-4000-a000-000000000024', array['people/00000000-0000-4000-c000-000000000093/20111031-fns-lsc-0086-6677153173-620623.webp', 'people/00000000-0000-4000-c000-000000000093/20111031-fns-lsc-0092-6677160011-3a0a14.webp']::text[], array['Cooks in white jackets prepping food in a kitchen', 'A commercial kitchen during dinner prep']::text[], array['USDAgov, Public domain, via Wikimedia Commons', 'USDAgov, Public domain, via Wikimedia Commons']::text[], true, now() - interval '65 hours'),
  ('00000000-0000-4000-c000-000000000104', 'update', 'Recovery hike with Steady Path this morning. Twenty-two of us, six miles, a lot of honest conversation.', '00000000-0000-4000-a000-000000000025', array['people/00000000-0000-4000-c000-000000000104/expedition-yellowstone-group-hik-6a7d88.webp']::text[], array['A line of hikers crossing a wide valley']::text[], array['Yellowstone National Park, Public domain, via Wikimedia Commons']::text[], true, now() - interval '132 hours'),
  ('00000000-0000-4000-c000-000000000118', 'update', 'Weekend hike to scout the trail Greenway is restoring next month. Hard to believe how much work goes into keeping a path like this open.', '00000000-0000-4000-a000-000000000004', array['people/00000000-0000-4000-c000-000000000118/geronimo-trail-scenic-byway-hiki-35cf0b.webp', 'people/00000000-0000-4000-c000-000000000118/grand-canyon-np-bright-angel-tra-fc475f.webp']::text[], array['Hikers on a forest trail', 'Hikers on a canyon trail with a wide view']::text[], array['Unknown authorUnknown author or not provided, Public domain, via Wikimedia Commons', 'Grand Canyon National Park, CC BY 2.0, via Wikimedia Commons']::text[], true, now() - interval '218 hours'),
  ('00000000-0000-4000-c000-000000000127', 'update', 'Restocking night at Harbor Table''s pantry. Shelves were empty at 6, full by 8.', '00000000-0000-4000-a000-000000000001', array['people/00000000-0000-4000-c000-000000000127/20111020-fns-lsc-0028-6629220815-61bf26.webp']::text[], array['A volunteer stocking shelves in a pantry']::text[], array['USDAgov, Public domain, via Wikimedia Commons']::text[], true, now() - interval '86 hours'),
  ('00000000-0000-4000-c000-000000000139', 'update', 'Cooked Tuesday dinner with the Harbor Table crew. 180 plates of chili and cornbread, and not a single one came back.', '00000000-0000-4000-a000-000000000001', array['people/00000000-0000-4000-c000-000000000139/airmen-volunteer-set-record-at-o-992b4a.webp']::text[], array['Volunteers in gloves cooking in a kitchen']::text[], array['Senior Airman Katrina Heikkinen, Public domain, via Wikimedia Commons']::text[], true, now() - interval '178 hours'),
  ('00000000-0000-4000-c000-000000000146', 'update', 'River cleanup by kayak. We pulled out a lawn chair, a shopping cart and roughly a thousand bottle caps.', '00000000-0000-4000-a000-000000000032', array['people/00000000-0000-4000-c000-000000000146/trinity-river-cleanup-npld-30860-5cfc54.webp']::text[], array['Volunteers in a kayak pulling a chair out of a river']::text[], array['Region 5 Photography, Public domain, via Wikimedia Commons']::text[], true, now() - interval '197 hours'),
  ('00000000-0000-4000-c000-000000000152', 'update', 'This week''s haul from the Seedline farmers'' stand. Buying from refugee farmers'' first businesses is the easiest good deed of my week.', '00000000-0000-4000-a000-000000000033', array['people/00000000-0000-4000-c000-000000000152/20180828-fns-pjk-0129-toned-4344-4face9.webp', 'people/00000000-0000-4000-c000-000000000152/20180828-fns-pjk-0148-toned-4434-e2d88e.webp', 'people/00000000-0000-4000-c000-000000000152/20180828-fns-pjk-1038-toned-4434-28323d.webp']::text[], array['A farm stand with baskets of vegetables', 'Fresh cauliflower and broccoli', 'An ear of corn among green husks']::text[], array['U.S. Department of Agriculture Preston Keres/Office of Communications-Photograp, Public domain, via Wikimedia Commons', 'U.S. Department of Agriculture Preston Keres/Office of Communications-Photograp, Public domain, via Wikimedia Commons', 'U.S. Department of Agriculture Preston Keres/Office of Communications-Photograp, Public domain, via Wikimedia Commons']::text[], true, now() - interval '46 hours'),
  ('00000000-0000-4000-c000-000000000161', 'update', 'Our first foster litter is three weeks old today. Eyes open, very loud, all gaining weight. Thank you Foster Kitten Network for the mentor and the supplies.', '00000000-0000-4000-a000-000000000036', array['people/00000000-0000-4000-c000-000000000161/1-month-old-kittens-32-c7a8d3.webp', 'people/00000000-0000-4000-c000-000000000161/ben-bengalian-kitten-4492540155-5b3e70.webp']::text[], array['A small tabby and white kitten', 'A young tabby cat looking up']::text[], array['0x010C, CC BY-SA 2.0, via Wikimedia Commons', 'Nickolas Titkov from Moscow, Russian Federation, CC BY-SA 2.0, via Wikimedia Commons']::text[], true, now() - interval '19 hours'),
  ('00000000-0000-4000-c000-000000000175', 'update', 'Mudflat restoration day with a Fernhill grantee. Ankle-deep and grinning.', '00000000-0000-4000-a000-000000000040', array['people/00000000-0000-4000-c000-000000000175/coastal-restoration-52-100243225-a8600c.webp', 'people/00000000-0000-4000-c000-000000000175/muddy-restoration-ecologists-651-b689cd.webp']::text[], array['A volunteer standing in a marsh in a sun hat', 'Volunteers resting on a mudflat during restoration']::text[], array['Tulane Public Relations, CC BY 2.0, via Wikimedia Commons', 'Pacific Southwest Region USFWS from Sacramento, US, Public domain, via Wikimedia Commons']::text[], true, now() - interval '252 hours'),
  ('00000000-0000-4000-c000-000000000188', 'update', 'The skatepark Kestrel''s teen committee funded is open, and it''s packed every afternoon. Teens deciding where the money goes really works.', '00000000-0000-4000-a000-000000000041', array['people/00000000-0000-4000-c000-000000000188/skatepark-crabtree-park-camberle-56964d.webp']::text[], array['A skatepark with ramps and a tower among trees']::text[], array['Mertbiol, CC0, via Wikimedia Commons']::text[], true, now() - interval '166 hours'),
  ('00000000-0000-4000-c000-000000000196', 'update', 'Visited two of the libraries Wrenfield funds. One is a century old, one is open until 9 every night. Both full.', '00000000-0000-4000-a000-000000000044', array['people/00000000-0000-4000-c000-000000000196/chethams-library-reading-room-9ea884.webp', 'people/00000000-0000-4000-c000-000000000196/loc-main-reading-room-highsmith-52444c.webp']::text[], array['An ornate library reading room', 'A grand domed library reading room']::text[], array['Michael D Beckwith, CC BY 3.0, via Wikimedia Commons', 'Carol M. Highsmith, Public domain, via Wikimedia Commons']::text[], true, now() - interval '288 hours'),
  ('00000000-0000-4000-c000-000000000203', 'update', 'Early morning at the harbor. Saltwind''s fall grants are keeping three working waterfront groups going here.', '00000000-0000-4000-a000-000000000045', array['people/00000000-0000-4000-c000-000000000203/early-morning-at-morro-bay-harbo-ac08e8.webp', 'people/00000000-0000-4000-c000-000000000203/early-morning-at-morro-bay-harbo-c3b597.webp']::text[], array['Fishing boats docked at dawn', 'A harbor at sunrise with boats on the water']::text[], array['ALAN SCHMIERER, CC0, via Wikimedia Commons', 'ALAN SCHMIERER, CC0, via Wikimedia Commons']::text[], true, now() - interval '331 hours'),
  ('00000000-0000-4000-c000-000000000217', 'update', 'Westside Arts Studio''s spring show was incredible. These are by students who''d never painted before September.', '00000000-0000-4000-a000-000000000009', array['people/00000000-0000-4000-c000-000000000217/danish-blue-large-abstract-paint-019122.webp', 'people/00000000-0000-4000-c000-000000000217/tomorrow-large-abstract-painting-ff0a43.webp']::text[], array['A large colorful abstract painting', 'A bright abstract painting in red, blue and yellow']::text[], array['Fons Heijnsbroek, CC0, via Wikimedia Commons', 'Fons Heijnsbroek, CC0, via Wikimedia Commons']::text[], true, now() - interval '120 hours'),
  ('00000000-0000-4000-c000-000000000231', 'update', 'Fields are ready for opening day. Volunteered to line them with Northside Youth Soccer, and now I''m signed up to coach.', '00000000-0000-4000-a000-000000000010', array['people/00000000-0000-4000-c000-000000000231/kids-soccer-practice-at-brastad-76eb6c.webp']::text[], array['A grass soccer field lined with trees']::text[], array['W.carter, CC BY 4.0, via Wikimedia Commons']::text[], true, now() - interval '271 hours'),
  ('00000000-0000-4000-c000-000000000244', 'update', 'Toured the new community health center a Bellweather grantee just opened. Primary care, dental and counseling, all under one roof.', '00000000-0000-4000-a000-000000000042', array['people/00000000-0000-4000-c000-000000000244/cleveland-state-community-colleg-b30878.webp']::text[], array['A modern brick community health center']::text[], array['Harrison Keely, CC BY 4.0, via Wikimedia Commons']::text[], true, now() - interval '365 hours'),
  ('00000000-0000-4000-c000-000000000258', 'update', 'Every unit in this building houses a family Keystone kept in their home this year. Rent help works.', '00000000-0000-4000-a000-000000000017', array['people/00000000-0000-4000-c000-000000000258/ansteth-flats-buffalo-new-york-2-9e07f2.webp']::text[], array['A row of apartment buildings on a city corner']::text[], array['Andre Carrotflower, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, now() - interval '422 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000001', 'call_volunteers', 'We need 12 more people for Saturday dinner crew this month. Four-hour shifts, 3 to 7 pm. You''ll prep, serve and sit down to eat with our guests. No experience needed, aprons provided.', 'https://example.org/01/volunteer', current_date + 4, null, array['00000000-0000-4000-a000-000000000001/pantry-team.jpg', '00000000-0000-4000-a000-000000000001/packing-boxes.jpg']::text[], array['Volunteers in green shirts working together in a food pantry', 'Volunteers packing grocery boxes labeled beans']::text[], array['USDAgov, public domain, via Wikimedia Commons', 'Chief Petty Officer Sarah Foster, public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '7 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000001', 'call_donations', 'Our walk-in cooler is 19 years old and losing the fight. A new compressor keeps 1,100 pounds of fresh produce a week safe. Every dollar goes to the repair.', 'https://example.org/01/give', current_date + 21, 8500, array['00000000-0000-4000-a000-000000000001/pantry-restock.jpg']::text[], array['A volunteer restocking food pantry shelves with a box of canned goods']::text[], array['USDAgov, public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '34 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000004', 'call_volunteers', 'Trail crew day on the river corridor: we''re re-benching the section that washed out in spring. Tools, gloves and lunch provided. Bring boots and water.', 'https://example.org/04/volunteer', current_date + 9, null, '{}'::text[], '{}'::text[], '{}'::text[], false, '00000000-0000-4000-a000-000000000004/trail-crew.webm', '00000000-0000-4000-a000-000000000004/trail-crew.jpg', 'Volunteers with hand tools re-cutting a dirt trail across a dry hillside', 'BLM Oregon & Washington, public domain, via Wikimedia Commons', now() - interval '22 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000004', 'call_donations', 'Help us replace 40 worn-out hand tools before spring season. $35 buys a pulaski or a McLeod that will last a decade of volunteers.', 'https://example.org/04/give', current_date + 30, 3200, array['00000000-0000-4000-a000-000000000004/deer-hill-trail-national-public-af6875.webp', '00000000-0000-4000-a000-000000000004/deer-hill-trail-national-public-c67534.webp']::text[], array['A trail crew member clearing brush among pine trees', 'Volunteers moving a fallen log off a trail']::text[], array['Coconino National Forest, Public domain, via Wikimedia Commons', 'Coconino National Forest, Public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '149 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000007', 'call_volunteers', 'Long-stay dogs need weekday morning walkers. One hour a week keeps them calm, healthy and adoptable. Orientation is 20 minutes and you''ll be walking the same day.', 'https://example.org/07/volunteer', current_date + 6, null, array['00000000-0000-4000-a000-000000000007/volunteer-golden.jpg', '00000000-0000-4000-a000-000000000007/volunteer-two-dogs.jpg']::text[], array['A volunteer crouching to greet a golden retriever at the shelter', 'A volunteer sitting on the ground hugging two shelter dogs']::text[], array['U.S. Navy photo by Petty Officer 2nd Class Kelly M Agee, public domain, via Wikimedia Commons', 'U.S. Navy photo by Petty Officer 2nd Class Kelly M Agee, public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '14 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000008', 'call_volunteers', 'Planting day on Delmar Street: 120 trees, 3 hours. Neighbors chose red maple and swamp white oak. We bring shovels, saplings and coffee.', 'https://example.org/08/volunteer', current_date + 24, null, array['00000000-0000-4000-a000-000000000008/planting-saplings.jpg', '00000000-0000-4000-a000-000000000008/carrying-trees.jpg', '00000000-0000-4000-a000-000000000008/planting-hillside.jpg']::text[], array['Volunteers kneeling to plant saplings in a field', 'A volunteer carrying young trees in bags along a trail', 'Volunteers in safety vests planting on a dry hillside']::text[], array['Christian Anold Mosha, CC BY-SA 4.0, via Wikimedia Commons', 'USFWS/Southeast, public domain, via Wikimedia Commons', 'Joshua Tree National Park, public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '26 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000008', 'call_donations', 'Each street tree costs $60 with a stake, mulch and two summers of watering. Help us plant the next 200 on the hottest blocks in the city.', 'https://example.org/08/give', current_date + 45, 12000, '{}'::text[], '{}'::text[], '{}'::text[], false, '00000000-0000-4000-a000-000000000008/bed-prep.webm', '00000000-0000-4000-a000-000000000008/bed-prep.jpg', 'A volunteer working soil in a garden bed', 'USDA, public domain, via Wikimedia Commons', now() - interval '108 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000009', 'call_donations', 'Our teens are out of acrylics and brushes. $25 keeps one student painting all semester. Help us stock the studio for 84 students.', 'https://example.org/09/give', current_date + 28, 2100, array['00000000-0000-4000-a000-000000000009/artist-ron-blackburn-painting-an-76e6ef.webp', '00000000-0000-4000-a000-000000000009/wall-painting.jpg']::text[], array['Silhouette of a painter at an easel', 'An artist in orange overalls painting a large black animal on a white wall']::text[], array['John H. White, Public domain, via Wikimedia Commons', 'Антон Хлабов, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '58 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000009', 'call_volunteers', 'Mural day on the 3rd Street underpass: we need adults to help prime walls and run the paint table. Teens lead the design.', 'https://example.org/09/volunteer', current_date + 12, null, '{}'::text[], '{}'::text[], '{}'::text[], false, '00000000-0000-4000-a000-000000000009/mural-pan.webm', '00000000-0000-4000-a000-000000000009/mural-pan.jpg', 'A long, colorful community mural along a street', 'Luis Alvaz, CC BY-SA 4.0, via Wikimedia Commons', now() - interval '187 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000014', 'call_volunteers', 'Screening night needs volunteer nurses and interpreters (Spanish, Somali). Three hours, Thursday evening, and you''ll help a neighbor find a doctor.', 'https://example.org/14/volunteer', current_date + 2, null, array['00000000-0000-4000-a000-000000000014/health-workers-class.jpg', '00000000-0000-4000-a000-000000000014/health-trainer.jpg']::text[], array['Community health workers taking notes during a training class', 'A trainer teaching a class of community health workers']::text[], array['Ness Kerson/madNESS Photography for AusAID, CC BY-SA 4.0, via Wikimedia Commons', 'Ness Kerson/madNESS Photography for AusAID, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '41 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000016', 'call_volunteers', 'Night drivers wanted: one route a week, about 3 hours. You pick up from grocers at closing and drop at pantries by 7 am. Van and fuel provided.', 'https://example.org/16/volunteer', null, null, array['00000000-0000-4000-a000-000000000016/2015-feds-feeds-families-gleanin-35f8f1.webp', '00000000-0000-4000-a000-000000000016/2015-feds-feeds-families-gleanin-99f538.webp']::text[], array['Sacks of potatoes ready for delivery in a warehouse', 'Boxes of donated food stacked in a warehouse']::text[], array['USDAgov, Public domain, via Wikimedia Commons', 'USDAgov, Public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '12 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000019', 'call_volunteers', 'Creek cleanup Saturday at Mill Creek. Waders for the first 20 people. Bring a friend and we''ll bring the coffee.', 'https://example.org/19/volunteer', current_date + 11, null, array['00000000-0000-4000-a000-000000000019/sharps-fire-planting-and-habitat-76e57a.webp']::text[], array['A restoration crew working across a valley']::text[], array['BLMIdaho, Public domain, via Wikimedia Commons']::text[], true, '00000000-0000-4000-a000-000000000019/crooked-river-23467104578.webm', '00000000-0000-4000-a000-000000000019/crooked-river-23467104578.jpg', 'A clear river flowing past rocks and fallen branches below cliffs', 'BLM Oregon & Washington, Public domain, via Wikimedia Commons', now() - interval '48 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000022', 'call_donations', 'Fishing line season: we''re treating 3 to 4 tangled birds a week. $300 covers a rescue run and first treatment. Help us get through the fall.', 'https://example.org/22/give', current_date + 31, 6000, array['00000000-0000-4000-a000-000000000022/june-23-2010-largest-bird-releas-5e376d.webp', '00000000-0000-4000-a000-000000000022/american-kestrel-44273-5b4ec8.webp']::text[], array['Volunteers releasing a rehabilitated pelican into the water', 'A kestrel perched on a handler''s glove']::text[], array['U.S. Department of the Interior, CC BY-SA 2.0, via Wikimedia Commons', 'Rhododendrites, CC BY-SA 4.0, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '29 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000024', 'call_volunteers', 'Thursday community dinner needs servers and dishwashers. Eat with us after. Our trainees cook; you help the room run.', 'https://example.org/24/volunteer', current_date + 2, null, array['00000000-0000-4000-a000-000000000024/20111031-fns-lsc-0110-6677167995-c640c7.webp', '00000000-0000-4000-a000-000000000024/20111031-fns-lsc-0131-6677173317-7d2288.webp']::text[], array['Cooks prepping food in a commercial kitchen', 'A tray of sliced potatoes ready for roasting']::text[], array['USDAgov, Public domain, via Wikimedia Commons', 'USDAgov, Public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '74 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000028', 'call_volunteers', 'Holiday sorting shifts are open. Two hours at the warehouse, no experience needed, and every box goes to a county pantry within the week.', 'https://example.org/28/volunteer', current_date + 8, null, array['00000000-0000-4000-a000-000000000028/20170922-osec-lsc-0197-366252589-3642b5.webp']::text[], array['Pallets of boxed food on tall warehouse shelves']::text[], array['U.S. Department of Agriculture, Public domain, via Wikimedia Commons']::text[], true, null, null, null, null, now() - interval '19 hours');
insert into posts (org_id, kind, body, action_url, action_date, goal_usd, image_paths, image_alts, image_credits, beneficiary_consent, video_path, video_poster_path, video_alt, video_credit, created_at) values ('00000000-0000-4000-a000-000000000032', 'call_volunteers', 'Last Sunday cleanup at the Canal Street launch. Kayakers especially welcome: there''s a lot the shore crew can''t reach.', 'https://example.org/32/volunteer', current_date + 18, null, array['00000000-0000-4000-a000-000000000032/trinity-river-cleanup-npld-31929-d49f55.webp', '00000000-0000-4000-a000-000000000032/september-15-2012-trash-collecte-54ab7f.webp']::text[], array['Kayakers paddling on a river', 'Filled trash bags and debris gathered beside a lake']::text[], array['Region 5 Photography, Public domain, via Wikimedia Commons', 'USEPA Environmental-Protection-Agency, Public domain, via Wikimedia Commons']::text[], true, '00000000-0000-4000-a000-000000000032/crooked-river-36648924083.webm', '00000000-0000-4000-a000-000000000032/crooked-river-36648924083.jpg', 'A wide river flowing past a grassy bank and a rocky slope', 'BLM Oregon & Washington, Public domain, via Wikimedia Commons', now() - interval '86 hours');
