insert into groups (id, slug, name, description, cause_slug, location, created_by, created_at) values ('00000000-0000-4000-e000-000000000001', 'portland-weekend-food-volunteers', 'Portland weekend food volunteers', 'Saturday kitchen shifts, pantry sorts and night food rescue runs around Portland. Swap shifts, find a ride, ask anything.', 'hunger', 'Portland, ME', '00000000-0000-4000-c000-000000000012', now() - interval '94 hours');
insert into group_members (group_id, user_id, joined_at) select '00000000-0000-4000-e000-000000000001', id, now() - make_interval(hours => abs(hashtext(id::text || 'portland-weekend-food-volunteers')) % 200) from profiles where id::text like '00000000-0000-4000-c000-%' and id <> '00000000-0000-4000-c000-000000000012' order by md5('portland-weekend-food-volunteers' || id::text) limit 46 on conflict do nothing;
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', '00000000-0000-4000-c000-000000000012', 'Welcome, everyone! This is the place to coordinate weekend shifts. Harbor Table''s Saturday dinner crew still needs 12 people this month.', now() - interval '70 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000001' and role = 'member' order by md5('portland-weekend-food-volunteers' || user_id::text) offset 2 limit 1), 'I can do the 3 to 7 this Saturday. First time, anything I should bring?', now() - interval '68 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', '00000000-0000-4000-c000-000000000012', 'Closed-toe shoes and an appetite. They feed volunteers after service.', now() - interval '67 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000001' and role = 'member' order by md5('portland-weekend-food-volunteers' || user_id::text) offset 6 limit 1), 'Eastgate is short a night driver on Thursdays if anyone has a license and three hours.', now() - interval '50 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000001' and role = 'member' order by md5('portland-weekend-food-volunteers' || user_id::text) offset 4 limit 1), 'I''ve done that route twice. The 5 am pantry drop is quiet and kind of beautiful.', now() - interval '49 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000001' and role = 'member' order by md5('portland-weekend-food-volunteers' || user_id::text) offset 8 limit 1), 'Anyone carpooling from the east side Saturday? I have two seats.', now() - interval '30 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000001' and role = 'member' order by md5('portland-weekend-food-volunteers' || user_id::text) offset 2 limit 1), 'Yes please! I''m near 82nd.', now() - interval '29 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000001' and role = 'member' order by md5('portland-weekend-food-volunteers' || user_id::text) offset 1 limit 1), 'Back from today''s shift. 140 dinners, and the new walk-in freezer is a game changer.', now() - interval '6 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000001', '00000000-0000-4000-c000-000000000012', 'Thank you all. Next Saturday''s sign-up is on Harbor Table''s page.', now() - interval '5 hours');
insert into groups (id, slug, name, description, cause_slug, location, created_by, created_at) values ('00000000-0000-4000-e000-000000000002', 'monthly-givers-circle', 'Monthly givers circle', 'People who give a little every month. We share how we choose, what we''ve learned, and what our giving became.', null, null, '00000000-0000-4000-c000-000000000031', now() - interval '164 hours');
insert into group_members (group_id, user_id, joined_at) select '00000000-0000-4000-e000-000000000002', id, now() - make_interval(hours => abs(hashtext(id::text || 'monthly-givers-circle')) % 200) from profiles where id::text like '00000000-0000-4000-c000-%' and id <> '00000000-0000-4000-c000-000000000031' order by md5('monthly-givers-circle' || id::text) limit 64 on conflict do nothing;
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', '00000000-0000-4000-c000-000000000031', 'Kicking this off: I give $40 a month split across three local groups. How do you all decide?', now() - interval '140 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000002' and role = 'member' order by md5('monthly-givers-circle' || user_id::text) offset 3 limit 1), 'I pick one cause a year and go deep. This year it''s housing.', now() - interval '139 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000002' and role = 'member' order by md5('monthly-givers-circle' || user_id::text) offset 7 limit 1), 'I check whether my employer matches first. Doubled my giving without changing my budget.', now() - interval '120 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000002' and role = 'member' order by md5('monthly-givers-circle' || user_id::text) offset 1 limit 1), 'That tip changed everything for me too. Ours matches up to $1,000.', now() - interval '98 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000002' and role = 'member' order by md5('monthly-givers-circle' || user_id::text) offset 10 limit 1), 'Does anyone else keep a giving journal? Seeing the year''s total made me want to keep going.', now() - interval '72 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', '00000000-0000-4000-c000-000000000031', 'I started one here last month. Logging is quick and it stays private.', now() - interval '71 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000002' and role = 'member' order by md5('monthly-givers-circle' || user_id::text) offset 5 limit 1), 'Lakeshore''s grant report on the walk-in freezer made my month. That''s where some of my gift went.', now() - interval '26 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000002', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000002' and role = 'member' order by md5('monthly-givers-circle' || user_id::text) offset 8 limit 1), 'Question for the group: one-time gifts or monthly? Organizations I asked prefer monthly so they can plan.', now() - interval '4 hours');
insert into groups (id, slug, name, description, cause_slug, location, created_by, created_at) values ('00000000-0000-4000-e000-000000000003', 'street-tree-planters', 'Street tree planters', 'Planting days, watering rotations and tree-care tips for the hottest blocks in the city.', 'environment', 'Boulder, CO', '00000000-0000-4000-c000-000000000048', now() - interval '120 hours');
insert into group_members (group_id, user_id, joined_at) select '00000000-0000-4000-e000-000000000003', id, now() - make_interval(hours => abs(hashtext(id::text || 'street-tree-planters')) % 200) from profiles where id::text like '00000000-0000-4000-c000-%' and id <> '00000000-0000-4000-c000-000000000048' order by md5('street-tree-planters' || id::text) limit 38 on conflict do nothing;
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000003', '00000000-0000-4000-c000-000000000048', 'Planting day on Delmar Street is set: 120 trees, three hours. Greenway brings shovels and coffee.', now() - interval '96 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000003', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000003' and role = 'member' order by md5('street-tree-planters' || user_id::text) offset 1 limit 1), 'Count me in. Should we bring our own gloves?', now() - interval '95 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000003', '00000000-0000-4000-c000-000000000048', 'Gloves are provided but bring your favorite pair if you have one.', now() - interval '94 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000003', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000003' and role = 'member' order by md5('street-tree-planters' || user_id::text) offset 4 limit 1), 'Watering rotation for the new trees starts next week. Two people per block, once a week, through October.', now() - interval '52 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000003', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000003' and role = 'member' order by md5('street-tree-planters' || user_id::text) offset 0 limit 1), 'I''ll take Maple and 9th.', now() - interval '51 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000003', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000003' and role = 'member' order by md5('street-tree-planters' || user_id::text) offset 6 limit 1), 'Saw the red maples leafing out on our block today. Small thing, big joy.', now() - interval '12 hours');
insert into groups (id, slug, name, description, cause_slug, location, created_by, created_at) values ('00000000-0000-4000-e000-000000000004', 'foster-kitten-network-fosters', 'Kitten fosters', 'Bottle babies, weigh-ins and the occasional 3 am question. Everyone welcome, from first-timers to old hands.', 'animals', 'Portland, OR', '00000000-0000-4000-c000-000000000066', now() - interval '104 hours');
insert into group_members (group_id, user_id, joined_at) select '00000000-0000-4000-e000-000000000004', id, now() - make_interval(hours => abs(hashtext(id::text || 'foster-kitten-network-fosters')) % 200) from profiles where id::text like '00000000-0000-4000-c000-%' and id <> '00000000-0000-4000-c000-000000000066' order by md5('foster-kitten-network-fosters' || id::text) limit 29 on conflict do nothing;
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000004', '00000000-0000-4000-c000-000000000066', 'New fosters: weigh daily at the same time and write it down. Steady gain is what matters.', now() - interval '80 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000004', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000004' and role = 'member' order by md5('foster-kitten-network-fosters' || user_id::text) offset 2 limit 1), 'My two are at 310g and 295g after week one. Is that on track?', now() - interval '60 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000004', '00000000-0000-4000-c000-000000000066', 'Right on track. Call the foster line if anyone drops two days in a row.', now() - interval '59 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000004', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000004' and role = 'member' order by md5('foster-kitten-network-fosters' || user_id::text) offset 5 limit 1), 'Heating pad tip: cover half the box so they can move off it when they want.', now() - interval '33 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000004', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000004' and role = 'member' order by md5('foster-kitten-network-fosters' || user_id::text) offset 1 limit 1), 'Ours go back for adoption Saturday. I already miss them.', now() - interval '9 hours');
insert into groups (id, slug, name, description, cause_slug, location, created_by, created_at) values ('00000000-0000-4000-e000-000000000005', 'youth-mentors', 'Youth mentors', 'Tutors and mentors who show up every week. Share what''s working, swap resources, and support each other.', 'youth', 'Austin, TX', '00000000-0000-4000-c000-000000000085', now() - interval '134 hours');
insert into group_members (group_id, user_id, joined_at) select '00000000-0000-4000-e000-000000000005', id, now() - make_interval(hours => abs(hashtext(id::text || 'youth-mentors')) % 200) from profiles where id::text like '00000000-0000-4000-c000-%' and id <> '00000000-0000-4000-c000-000000000085' order by md5('youth-mentors' || id::text) limit 34 on conflict do nothing;
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000005', '00000000-0000-4000-c000-000000000085', 'One hour a week, same student, all year. That consistency is the whole thing.', now() - interval '110 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000005', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000005' and role = 'member' order by md5('youth-mentors' || user_id::text) offset 3 limit 1), 'Our coding club has a waitlist of 40 teens. If you know JavaScript, they''d love you.', now() - interval '88 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000005', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000005' and role = 'member' order by md5('youth-mentors' || user_id::text) offset 1 limit 1), 'Anyone have good reading games for third graders? Mine is losing interest in flashcards.', now() - interval '60 hours');
insert into messages (group_id, author_id, body, created_at) values ('00000000-0000-4000-e000-000000000005', (select user_id from group_members where group_id = '00000000-0000-4000-e000-000000000005' and role = 'member' order by md5('youth-mentors' || user_id::text) offset 4 limit 1), 'We play ''read the menu'' with real takeout menus. Works every time.', now() - interval '59 hours');
