select n.id, p.id from org_needs n cross join lateral (
  select id from profiles where id::text like '00000000-0000-4000-c000-%' order by md5(n.id::text || id::text) limit 3 + (abs(hashtext(n.id::text)) % 22)
) p where n.kind = 'volunteer' and n.met_at is null on conflict do nothing;




-- Comments: 2 to 29 people per post, spread between the post time and now.
select p.id, d.id,
       replace((case when o.org_type = 'foundation' then array['Thank you for funding local groups that actually do the work.', 'Love that you publish every grant here.', 'Multi-year support is such a big deal for small nonprofits. Thank you.', 'Great to see {org} backing grassroots groups.', 'I give through this fund. Seeing the grantee reports makes it real.', 'Any plans to fund more youth programs next cycle?', 'Transparent grantmaking. More of this, please.', 'So glad the grantees confirm each grant publicly.', 'How do small groups without a development team apply?', 'This is the kind of philanthropy I want to support.', 'This is why I give. Thank you, {org}.', 'Love seeing the actual numbers. Keep posting these.', 'Shared this with my book club.', 'What a week. Thank you to every volunteer.', 'This made my morning.', 'Proud to be a monthly donor.', 'My neighbor volunteers with you and never stops talking about it.', 'Thank you for telling this with so much respect.', 'How can someone new get involved?', 'Sending this to my company''s giving committee.', 'Incredible progress since spring.', 'I walked past last Saturday and the energy was amazing.', 'Small gift coming your way this month.', 'Thank you for being so transparent about where the money goes.', 'The volunteers in this photo deserve all the credit.', 'We need more of this in our city.', 'Keep going. People notice.', 'Is there a way to sponsor this directly?', 'My kids and I picked {org} for our family gift this year. This is why.', 'Amazing team. Amazing work.', 'Love that you share the hard parts too.', 'This is what community looks like.', 'Thank you for showing up, every single week.', 'Just signed up to volunteer. See you soon!', 'Congrats to the whole crew.', 'Reading this on the bus and smiling.', 'Our church collected for you last month. So glad to see the results.', 'Wow. That''s a lot of people helped.', 'You all make this city better.', 'Following for more updates like this.', 'Do you take in-kind donations?', 'The best kind of news.', 'I was helped by a group like this years ago. Thank you for doing it now.', 'Can''t wait to see what''s next.', 'Grateful you exist.', 'Shared with my neighborhood group.']
                     when p.kind in ('ask', 'call_volunteers', 'call_donations') then array['Signed up!', 'Dropping some off this weekend.', 'Shared with my building''s group chat.', 'Just sent a little.', 'My office is doing a drive for this next week.', 'Count me in for Saturday.', 'Is there a wish list somewhere?', 'This is why I give. Thank you, {org}.', 'Love seeing the actual numbers. Keep posting these.', 'Shared this with my book club.', 'What a week. Thank you to every volunteer.', 'This made my morning.', 'Proud to be a monthly donor.', 'My neighbor volunteers with you and never stops talking about it.', 'Thank you for telling this with so much respect.', 'How can someone new get involved?', 'Sending this to my company''s giving committee.', 'Incredible progress since spring.', 'I walked past last Saturday and the energy was amazing.', 'Small gift coming your way this month.', 'Thank you for being so transparent about where the money goes.', 'The volunteers in this photo deserve all the credit.', 'We need more of this in our city.', 'Keep going. People notice.', 'Is there a way to sponsor this directly?', 'My kids and I picked {org} for our family gift this year. This is why.', 'Amazing team. Amazing work.', 'Love that you share the hard parts too.', 'This is what community looks like.', 'Thank you for showing up, every single week.', 'Just signed up to volunteer. See you soon!', 'Congrats to the whole crew.', 'Reading this on the bus and smiling.', 'Our church collected for you last month. So glad to see the results.', 'Wow. That''s a lot of people helped.', 'You all make this city better.', 'Following for more updates like this.', 'Do you take in-kind donations?', 'The best kind of news.', 'I was helped by a group like this years ago. Thank you for doing it now.', 'Can''t wait to see what''s next.', 'Grateful you exist.', 'Shared with my neighborhood group.']
                     else array['This is why I give. Thank you, {org}.', 'Love seeing the actual numbers. Keep posting these.', 'Shared this with my book club.', 'What a week. Thank you to every volunteer.', 'This made my morning.', 'Proud to be a monthly donor.', 'My neighbor volunteers with you and never stops talking about it.', 'Thank you for telling this with so much respect.', 'How can someone new get involved?', 'Sending this to my company''s giving committee.', 'Incredible progress since spring.', 'I walked past last Saturday and the energy was amazing.', 'Small gift coming your way this month.', 'Thank you for being so transparent about where the money goes.', 'The volunteers in this photo deserve all the credit.', 'We need more of this in our city.', 'Keep going. People notice.', 'Is there a way to sponsor this directly?', 'My kids and I picked {org} for our family gift this year. This is why.', 'Amazing team. Amazing work.', 'Love that you share the hard parts too.', 'This is what community looks like.', 'Thank you for showing up, every single week.', 'Just signed up to volunteer. See you soon!', 'Congrats to the whole crew.', 'Reading this on the bus and smiling.', 'Our church collected for you last month. So glad to see the results.', 'Wow. That''s a lot of people helped.', 'You all make this city better.', 'Following for more updates like this.', 'Do you take in-kind donations?', 'The best kind of news.', 'I was helped by a group like this years ago. Thank you for doing it now.', 'Can''t wait to see what''s next.', 'Grateful you exist.', 'Shared with my neighborhood group.'] end)[1 + (abs(hashtext(p.id::text || 'body')) + d.rn) %
               (case when o.org_type = 'foundation' then 46 when p.kind in ('ask', 'call_volunteers', 'call_donations') then 43 else 36 end)], '{org}', o.name),
       p.created_at + (now() - p.created_at) * ((abs(hashtext(p.id::text || d.id::text)) % 950) / 1000.0)
  from posts p join orgs o on o.id = p.org_id
  cross join lateral (
    select id, row_number() over (order by md5(p.id::text || id::text || 'comment')) rn from profiles
     where id::text like '00000000-0000-4000-c000-%'
     order by md5(p.id::text || id::text || 'comment') limit 2 + abs(hashtext(p.id::text || 'comments')) % 28
  ) d
 where p.published;

-- Comments on donor posts (F-079).
select p.id, d.id, (array['Thanks for sharing this!', 'Just signed up. See you Saturday.', 'Sharing with my neighborhood group.', 'This is so good to know.', 'I didn''t know about this. Thank you.', 'Love this. Following them now.', 'Same experience here, highly recommend.', 'Going to bring my kids next time.', 'Thank you for spreading the word.', 'Sent them a little something.', 'Great tip, I just checked my employer''s match.', 'This made my day.', 'Where do I sign up?', 'Saving this for the weekend.', 'So glad they exist.'])[1 + (abs(hashtext(p.id::text || 'dbody')) + d.rn) % 15],
       p.created_at + (now() - p.created_at) * ((abs(hashtext(p.id::text || d.id::text)) % 950) / 1000.0)
  from posts p
  cross join lateral (
    select id, row_number() over (order by md5(p.id::text || id::text || 'dc')) rn from profiles
     where id::text like '00000000-0000-4000-c000-%' and id <> p.author_id
     order by md5(p.id::text || id::text || 'dc') limit 2 + abs(hashtext(p.id::text || 'dcomments')) % 9
  ) d
 where p.org_id is null and p.published;

-- Team replies (LinkedIn "Author" replies) under one or two comments on about half the posts.
select c.post_id, c.id, m.user_id, (array['Thank you so much. This means a lot to our whole team.', 'Thank you for being here with us.', 'We''d love to have you! Details are on our profile under Current needs.', 'Thank you! We''ll keep sharing updates.', 'Our volunteers will be so happy to read this.', 'Thank you. Every gift really does add up.', 'Yes! Send us a note through the Help link and we''ll get you started.', 'Grateful for you. See you soon.'])[1 + abs(hashtext(c.id::text || 'reply')) % 8], true,
       least(now() - interval '5 minutes', c.created_at + interval '2 hours')
  from (select c.*, row_number() over (partition by post_id order by md5(id::text)) rn from comments c) c
  join posts p on p.id = c.post_id
  cross join lateral (select user_id from org_members where org_id = p.org_id order by created_at, user_id limit 1) m
 where c.rn <= 1 + abs(hashtext(p.id::text)) % 2 and abs(hashtext(p.id::text || 'reply')) % 10 < 5;

-- People reply to each other under about one comment in six.
select c.post_id, c.id, r.id, (array['Couldn''t agree more.', 'Same here!', 'See you there!', 'This is exactly why I started volunteering too.', 'Well said.', 'Thanks for sharing that.', 'I''m going Saturday too. Say hi!', 'Love this.', 'So true.', 'My family feels the same way.', 'Their volunteer orientation is great, highly recommend.', 'Yes! Signed up after reading this.'])[1 + abs(hashtext(c.id::text || r.id::text)) % 12],
       least(now() - interval '2 minutes', c.created_at + make_interval(mins => 10 + abs(hashtext(c.id::text || 'peer')) % 600))
  from comments c
  cross join lateral (
    select id from profiles where id::text like '00000000-0000-4000-c000-%' and id <> c.user_id
     order by md5(c.id::text || id::text) limit 1 + abs(hashtext(c.id::text || 'n')) % 2
  ) r
 where c.parent_id is null and not c.as_org and abs(hashtext(c.id::text || 'peer')) % 6 = 0;

-- About 4 in 10 commenters logged a gift to that org before commenting.
select distinct on (c.user_id, p.org_id) c.user_id, p.org_id,
       (array[10, 20, 25, 50, 50, 100, 100, 250, 500])[1 + abs(hashtext(c.user_id::text || p.org_id::text)) % 9],
       (c.created_at - make_interval(days => 3 + abs(hashtext(c.id::text || 'gift')) % 200))::date, null
  from comments c join posts p on p.id = c.post_id
 where not c.as_org and c.user_id::text like '00000000-0000-4000-c000-%' and abs(hashtext(c.user_id::text || p.org_id::text || 'gave')) % 10 < 4;
-- Two in three demo people show the Donor badge.
update profiles set donor_badge = true where id::text like '00000000-0000-4000-c000-%' and abs(hashtext(id::text || 'badge')) % 3 < 2;

update profiles set avatar_url = '/avatars/' || handle
 where id::text like '00000000-0000-4000-c000-%' or handle = 'dana_demo';

